#!/usr/bin/env -S deno run -A
import { expr, job, step, workflow } from "jsr:@david/gagen@0.8.0";

const checkout = step({ name: "Checkout", uses: "actions/checkout@v7", with: { "persist-credentials": false } });
const setupDeno = step({ uses: "denoland/setup-deno@v2" });
const installDeps = step.dependsOn(checkout)({ name: "Install dependencies", run: "npm install" });

const ciJob = job("ci", {
  name: "CI",
  runsOn: "ubuntu-latest",
  permissions: { contents: "read" },
  steps: step(
    step.dependsOn(checkout)({
      uses: "dprint/check@v2",
      with: { cache: true },
    }),
    step.dependsOn(checkout, setupDeno)({
      name: "Lint CI generation",
      run: "./.github/workflows/ci.ts --lint",
    }),
    step.dependsOn(installDeps)({ name: "Type check", run: "npx tsc --noEmit" }),
    step.dependsOn(installDeps)({
      name: "Run tests",
      run: "npx vitest run",
      env: {
        // the tests make requests to the GitHub API, which rate limits
        // unauthenticated requests by the IP address of the shared runner
        DPRINT_PLUGINS_GH_TOKEN: expr("secrets.GITHUB_TOKEN"),
      },
    }),
  ),
});

workflow({
  name: "CI",
  on: {
    pull_request: { branches: ["main"] },
    push: { branches: ["main"] },
  },
  permissions: {},
  concurrency: {
    // https://stackoverflow.com/a/72408109/188246
    group: "${{ github.workflow }}-${{ github.head_ref || github.run_id }}",
    cancelInProgress: true,
  },
  jobs: [ciJob],
}).writeOrLint({
  filePath: new URL("./ci.generated.yml", import.meta.url),
  header: "# GENERATED BY ./ci.ts -- DO NOT DIRECTLY EDIT",
});
